# typed: false
# frozen_string_literal: true

require "pathname"

# A self-contained tool tree as a release of a Ruby project lays it —
# manifest, lock, Gemfile, executables under exe/ — for the tests that
# read, vendor, wrap or package one. Pure builders over a directory the
# test owns; no state is shared.
module ToolTreeFixtures
  # A lock pinning the Ruby the tree runs under.
  RUBY_LOCK = <<~YAML
    # Generated by dev. Do not edit.

    ruby:
      ruby:
        group: app
        version: 4.0.6
        tap: d3mlabs/d3mlabs
        version_suffix: 4.0.6
  YAML

  # A lock pinning a formula and no Ruby.
  FORMULA_LOCK = "brew:\n  zstd:\n    group: app\n    version: 1.5.6\n"

  # @param tree [Pathname] where the tree is laid; created
  # @param lock [String] the deps.lock body
  # @param exes [Array<String>] names under exe/; the directory exists even when empty
  # @param gemfile [Boolean] whether the tree carries a Gemfile
  # @return [Pathname] the tree
  def tool_tree(tree, lock: RUBY_LOCK, exes: ["ai-flow"], gemfile: true)
    (tree / "exe").mkpath
    (tree / "dependencies.rb").write("Dev::Deps.define { ruby \"4.0.6\" }\n")
    (tree / "deps.lock").write(lock)
    (tree / "Gemfile").write(%(source "https://rubygems.org"\n)) if gemfile
    exes.each do |name|
      exe = tree / "exe" / name
      exe.write("#!/usr/bin/env ruby\nputs \"#{name} says \#{ARGV.join(' ')}\"\n")
      exe.chmod(0o755)
    end
    tree
  end
end
